// PAINT-COLOR SCANNER (owner: never show red/blue/green cars, even when the ad doesn't say the
// color). Downscales each car's photos with macOS `sips`, reads the pixels (BMP), and measures
// how much of the CENTER of the frame is strongly red/blue/green. A car is flagged only when
// MULTIPLE photos agree (one blue-sky shot can't flag it). Flagged cars get e.color set in
// manual.json so the build's color filter drops them. Prints "FLAGGED n".
const fs=require('fs'), path=require('path'), cp=require('child_process');
const ROOT=path.join(__dirname,'..');
const TMP='/tmp/cscan-'+process.pid+'.bmp';

function pixels(img){ // -> array of [r,g,b] from a 40x40 downscale, or null
  try{
    cp.execSync(`sips -z 40 40 -s format bmp "${img}" --out "${TMP}" >/dev/null 2>&1`);
    const b=fs.readFileSync(TMP);
    const off=b.readUInt32LE(10), w=b.readInt32LE(18), h=Math.abs(b.readInt32LE(22)), bpp=b.readUInt16LE(28)/8;
    const rowSz=Math.ceil(w*bpp/4)*4, out=[];
    for(let y=0;y<h;y++){ for(let x=0;x<w;x++){ const p=off+y*rowSz+x*bpp; out.push([b[p+2],b[p+1],b[p]]); } } // BGR
    return {px:out,w,h};
  }catch(e){return null;}
}
function centerStats(P){ // fraction of strong red/blue/green pixels in the middle half of the frame
  const {px,w,h}=P; let n=0,red=0,blue=0,green=0;
  for(let y=Math.floor(h*0.3);y<Math.floor(h*0.85);y++){ // skip top 30% (sky) and lowest strip (road)
    for(let x=Math.floor(w*0.2);x<Math.floor(w*0.8);x++){
      const [r,g,b]=px[y*w+x]; n++;
      if(r>85&&g<r*0.55&&b<r*0.6) red++;
      else if(b>85&&r<b*0.7&&g<b*0.82) blue++;
      else if(g>75&&r<g*0.75&&b<g*0.8) green++;
    }
  }
  return {red:red/n,blue:blue/n,green:green/n};
}
(async()=>{
  const MANUAL=path.join(ROOT,'_tools','manual.json');
  const manual=JSON.parse(fs.readFileSync(MANUAL,'utf8'));
  const built=new Set(JSON.parse(fs.readFileSync(path.join(ROOT,'cars.json'),'utf8')).filter(c=>c.src).map(c=>c.src.split('/').pop()));
  const targets=manual.filter(e=>e.type!=='Land'&&e.type!=='House'&&!e.color&&e.imgs&&e.imgs.length&&e.src&&built.has(e.src.split('/').pop()));
  let flagged=0;
  for(const e of targets){
    const votes={red:0,blue:0,green:0}; let checked=0;
    for(const im of e.imgs.slice(0,5)){ // first 5 photos
      const P=pixels(path.join(ROOT,im.replace(/^\//,''))); if(!P)continue; checked++;
      const s=centerStats(P);
      if(s.red>0.28)votes.red++; if(s.blue>0.28)votes.blue++; if(s.green>0.28)votes.green++;
    }
    if(checked<2)continue;
    const need=Math.max(2,Math.ceil(checked*0.5)); // majority of sampled photos must agree
    let col=null;
    if(votes.red>=need)col='red'; else if(votes.blue>=need)col='blue'; else if(votes.green>=need)col='green';
    if(col){ e.color=col; flagged++; console.error('  FLAGGED '+col.toUpperCase()+': '+e.year+' '+e.make+' '+e.model+' $'+e.price+' (votes '+votes[col]+'/'+checked+')'); }
  }
  try{fs.unlinkSync(TMP);}catch(x){}
  if(flagged)fs.writeFileSync(MANUAL,JSON.stringify(manual,null,1));
  console.log('FLAGGED '+flagged+' (scanned '+targets.length+' vehicles by photo pixels)');
})();

const fs=require('fs');
let s=fs.readFileSync('_tools/gen.js','utf8');
const rep=[];
function R(name,from,to){ if(s.indexOf(from)>=0){s=s.split(from).join(to);rep.push('  '+name+' ✓');} else rep.push('  '+name+' ✗ NOT FOUND'); }

