console.log('  -- gen.js Contact Us left:', (s.match(/Contact Us/g)||[]).length, '| /about left:', (s.match(/\/about/g)||[]).length, '| cmOverlay left:', (s.match(/cmOverlay/g)||[]).length);

const fs=require('fs');
