// 4) contact modal markup — remove entire cm-overlay block
const before=s.length;
s=s.replace(/\s*<div class="cm-overlay" id="cmOverlay" hidden>[\s\S]*?<\/form>\s*<\/div>\s*<\/div>/, '');
rep.push(s.length<before ? '  contact-modal ✓' : '  contact-modal ✗ NOT FOUND');

