  '<style>.dealbadge{display:inline-block;background:#1a7f37;color:#fff;font-weight:800;font-size:11.5px;letter-spacing:.03em;padding:3px 9px;border-radius:999px;margin:0 auto 5px}'
  +'.chip-prius{border-color:#1a7f37!important;color:#1a7f37;font-weight:800}'
