function modelCards(list){
  return list.map(function(c){
    var img=(c.imgs&&c.imgs[0])||c.hero||'';
    var name=c.year+' '+c.make+' '+c.model;
    var price=(c.price>1000)?('$'+Number(c.price).toLocaleString()):'Call';
    var mi=(c.miles!=null)?(Number(c.miles).toLocaleString()+' miles'):'';
    return '<a class="mcard" href="/cars/'+c.slug+'">'
      +(img?('<span class="mimg"><img src="'+esc(img)+'" alt="'+esc(name)+'" loading="lazy" decoding="async" width="320" height="240"></span>'):'')
      +'<span class="mtxt"><strong>'+esc(name)+'</strong><span class="mpr">'+price+'</span>'
      +(mi?('<span class="mmi">'+esc(mi)+'</span>'):'')
      +(c.location?('<span class="mloc">📍 '+esc(c.location)+'</span>'):'')
      +'</span></a>';
  }).join('');
}
