.soon-card{position:relative;background:#fff;border-radius:20px;max-width:400px;width:100%;padding:40px 32px 32px;text-align:center;box-shadow:0 24px 60px rgba(8,20,40,.35);animation:soonPop .22s cubic-bezier(.2,.8,.3,1)}@keyframes soonPop{from{transform:translateY(14px) scale(.96);opacity:0}to{transform:none;opacity:1}}
.soon-x{position:absolute;top:10px;right:14px;background:none;border:none;font-size:26px;line-height:1;color:var(--muted);cursor:pointer;padding:4px}.soon-emoji{font-size:60px;line-height:1;margin-bottom:14px}
.soon-badge{display:inline-block;background:var(--blue);color:#fff;font-weight:800;font-size:12px;letter-spacing:.14em;text-transform:uppercase;padding:6px 14px;border-radius:999px;margin-bottom:16px}
.soon-card h2{font-size:22px;color:var(--blue-dk);margin:0 0 10px}.soon-card p{color:var(--muted);font-size:15px;line-height:1.55;margin:0 0 8px}.soon-dom{color:var(--blue);font-weight:700;font-size:14px;margin:0 0 22px}
.soon-btn{background:var(--blue);color:#fff;border:none;border-radius:999px;font-weight:700;font-size:15px;padding:12px 30px;cursor:pointer;font-family:inherit}.soon-btn:hover{background:var(--blue-dk)}
.cbtn{display:block;text-align:center;background:var(--blue);color:#fff;font-weight:700;padding:12px;border-radius:999px;text-decoration:none;margin-bottom:10px;cursor:pointer;font-family:inherit;font-size:13px}.cbtn:hover{background:var(--blue-dk)}
.cbtn.alt{background:#fff;color:var(--blue);border:2px solid var(--line)}
dl.specs{margin:18px 0 0;border-top:1px solid var(--line)}.srow{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid var(--line);font-size:14px}.srow dt{color:var(--muted);margin:0}.srow dd{margin:0;font-weight:600;text-align:right}
.desc{margin:34px 0;background:#fff;border:1px solid var(--line);border-radius:14px;padding:24px 28px}.desc h2{font-size:20px;margin-top:0}.desc p{color:#26384d;max-width:75ch;text-align:justify;hyphens:auto;font-size:1.2em;line-height:1.6;margin-bottom:0}
.faq{margin:34px 0;background:#fff;border:1px solid var(--line);border-radius:14px;padding:24px 28px}.faq h2{font-size:20px;margin:0 0 14px}.faq .qa{margin:0 0 16px}.faq .qa:last-child{margin-bottom:0}.faq h3{font-size:16px;margin:0 0 4px;color:var(--text)}.faq p{color:#26384d;margin:0;max-width:75ch;text-align:justify;hyphens:auto}
.facts{margin:34px 0;background:var(--bg2);border:1px solid var(--line);border-radius:14px;padding:22px 24px}.facts h2{font-size:20px;margin:0 0 4px}.factnote{color:var(--muted);font-size:13px;max-width:75ch;margin:0 0 14px;text-align:justify}.facts dl.specs{margin:0;border-top:1px solid var(--line)}.factnote2{color:#26384d;margin:14px 0 0;max-width:75ch;text-align:justify;hyphens:auto}
footer.site{background:var(--blue-dk);color:#cfe0ff;padding:34px 20px;text-align:center;margin-top:40px;font-size:13px;position:relative}
html{background:linear-gradient(to bottom,#ffffff 0%,#ffffff 50%,#0a3880 50%,#0a3880 100%)}
.back{display:inline-block;margin:26px 0 0;font-weight:700;text-decoration:none}
@media(prefers-reduced-motion:reduce){*{transition:none!important}}
