(async function () {
  let cars;
  if (process.env.FROMCACHE && fs.existsSync(CACHE)) {
    cars = JSON.parse(fs.readFileSync(CACHE, 'utf8'));
    console.log('FROMCACHE: ' + cars.length + ' cars (no scrape)');
  } else {
    cars = await scrapeListings();
    const before = cars.length;
    cars = cars.filter(c => !(c.type === 'Other' || (c.type === 'Truck' && c.year >= 2013) || /smrt fortwo|smart fortwo/i.test(c.make + ' ' + c.model)));
    console.log('listings ' + before + ' → kept classics ' + cars.length + ' — fetching galleries…');
    let done = 0;
    for (let i = 0; i < cars.length; i += 5) {
      await Promise.all(cars.slice(i, i + 5).map(async function (c) {
        try { c.imgs = galThumb(decode(await get('https://www.atomicmotors.net' + c.durl)), '640x480').slice(0, 24); } catch (e) { c.imgs = c.thumbs; }
        if (!c.imgs.length) c.imgs = c.thumbs;
        done++;
      }));
      process.stdout.write('\r  galleries ' + done + '/' + cars.length);
    }
    console.log('');
    // SOLD detection: a car that has dropped out of the Atomic Motors feed is NOT deleted —
    // it's kept on the site and flagged sold:true (with the date it disappeared). Cars currently
    // in the feed are available (sold:false). A car that comes back in the feed auto-un-sells.
    cars.forEach(function (c) { c.sold = false; delete c.soldAt; });
    var liveIds = {}; cars.forEach(function (c) { if (c.oid != null) liveIds[c.oid] = 1; });
    var today = new Date().toISOString().slice(0, 10);
    var prior = [];
    try { if (fs.existsSync(CACHE)) prior = JSON.parse(fs.readFileSync(CACHE, 'utf8')) || []; } catch (e) {}
    var soldCount = 0;
    prior.forEach(function (p) {
      if (p && p.oid != null && !liveIds[p.oid]) { p.sold = true; if (!p.soldAt) p.soldAt = today; cars.push(p); soldCount++; }
    });
    if (soldCount) console.log(soldCount + ' car(s) gone from feed → kept as SOLD');
    fs.writeFileSync(CACHE, JSON.stringify(cars)); // roster = live + previously-sold
    console.log('cached → ' + CACHE);
  }

  // manual removals (owner-requested; applies in both scrape & FROMCACHE modes)
  const DROP = ['1975 triumph tr6'];
  cars = cars.filter(c => DROP.indexOf((c.year + ' ' + c.make + ' ' + c.model).toLowerCase()) < 0);

  // manually-added cars (private-party / off-feed listings, e.g. from Facebook).
  // These are NOT in the dealer scrape, so they live in _tools/manual.json and are merged
  // every run — that way a full re-scrape can't wipe them. Their price is shown AS-IS (no
  // 10% markup) and their photos are already local files (no CDN hero download).
  // ===== ATOMIC MOTORS DEALER FEED SWITCH =====
  // Owner paused the Atomic Motors partnership 2026-07-05. Set to true to restore all dealer cars.
  const INCLUDE_DEALER_FEED = false;
  if (!INCLUDE_DEALER_FEED) {
    const before = cars.length;
    cars = [];
    console.log('dealer feed OFF — removed ' + before + ' Atomic Motors car(s)');
  }
  try {
    const MANUAL = path.join(__dirname, 'manual.json');
    if (fs.existsSync(MANUAL)) {
      const man = JSON.parse(fs.readFileSync(MANUAL, 'utf8')) || [];
      man.forEach(function (m) { m._manual = true; if (!m.thumbs) m.thumbs = m.imgs || []; });
      cars = cars.concat(man);
      if (man.length) console.log('merged ' + man.length + ' manual car(s) from manual.json');
    }
  } catch (e) { console.log('manual.json skipped: ' + e.message); }

  // 25-YEAR RULE (owner, 2026-07-02): the site lists true classics only — any vehicle newer
  // than 25 years old is excluded (dealer AND manual). Rolls forward automatically each year.
  const MAXYEAR = new Date().getFullYear() - 25;
  // EXEMPTIONS (owner): these models are imported regardless of age —
  //   Toyota Prius (2026-07-05, 2010-2015 sweep) · Lexus SC 430 (2026-07-06, all years).
  const yearExempt = c => /prius|sc ?-?430|tesla/i.test(c.make + ' ' + c.model);
  const tooNew = cars.filter(c => c.year > MAXYEAR && !yearExempt(c)).length;
  cars = cars.filter(c => c.year <= MAXYEAR || yearExempt(c));
  if (tooNew) console.log(tooNew + ' vehicle(s) newer than ' + MAXYEAR + ' excluded (25-year rule)');

  // NO "PRICE ON REQUEST" (owner, 2026-07-03): every listing must show a real price.
  // Cars whose price would display as "Price on request" (price <= $1000 or missing) are excluded.
  // Antiques are legitimately cheap ($50+) — exempt them from the $1000 floor; everything else must be >$1000.
  const noPrice = cars.filter(c => c.type !== 'Antique' && c.type !== 'Rental' && c.type !== 'Ebike' && c.type !== 'Free' && c.type !== 'Foreclosure' && c.type !== 'PVCars' && c.type !== 'Room' && c.type !== 'Batman' && !(c.price > 1000)).length;
  cars = cars.filter(c => (c.type === 'Free' || c.type === 'Foreclosure') ? true : (c.type === 'Antique' || c.type === 'Rental' || c.type === 'Ebike' || c.type === 'PVCars' || c.type === 'Room' || c.type === 'Batman') ? c.price > 40 : c.price > 1000);
  if (noPrice) console.log(noPrice + " vehicle(s) without a displayable price excluded (no price-on-request rule)");

  // FRESH-ONLY (owner 2026-07-10): drop vehicle-cars that have been ON THE MARKET (Craigslist posted date)
  // more than 5 days — keep only fresh listings. Property/rentals/rooms/ebikes/RVs/foreclosures are EXEMPT
  // (they legitimately stay listed for weeks). Cars with no post date are kept (can't prove they're stale).
  {
    const FRESH_EXEMPT = { Land:1, House:1, Business:1, Antique:1, Rental:1, Room:1, Ebike:1, Foreclosure:1, RV:1, PVCars:1, Batman:1 };
    const cutTs = Date.now() - 5 * 86400000;
    const stale = cars.filter(c => !FRESH_EXEMPT[c.type] && c.postedTs && Date.parse(c.postedTs) && Date.parse(c.postedTs) < cutTs).length;
    cars = cars.filter(c => FRESH_EXEMPT[c.type] || !c.postedTs || !Date.parse(c.postedTs) || Date.parse(c.postedTs) >= cutTs);
    if (stale) console.log(stale + ' car(s) removed — on the market >5 days (owner freshness rule)');
  }

  // NO PROJECT / NON-RUNNING CARS (owner, 2026-07-05) — owner only wants cars that drive.
  // EXEMPTION: Toyota Prius is always kept (owner is good at fixing them).
  const JUNK = /\b(project car|projects?\b|parts car|parts only|for parts|not runn|non[- ]?runn|does ?n['’]?t run|do(es)? not run|won['’]?t run|no run\b|does ?n['’]?t start|do(es)? not start|won['’]?t start|no start\b|needs? (a )?(engine|motor|transmission|head gasket|rebuild)|blown (engine|motor|head)|engine (is )?(seized|blown|out)|seized (engine|motor)|mechanic['’]?s? special|rolling shell|roller\b|no engine|no motor)/i;
  const isPriusJ = c => /prius/i.test((c.make || '') + ' ' + (c.model || '')) || c.type === 'Land' || c.type === 'House' || c.type === 'Business' || c.type === 'Antique' || c.type === 'Rental' || c.type === 'Ebike' || c.type === 'Free' || c.type === 'Foreclosure' || c.type === 'PVCars' || c.type === 'Room' || c.type === 'Batman'; // land listings often say "project" etc. — junk regex is car-specific
  const junkList = cars.filter(c => !isPriusJ(c) && JUNK.test((c.desc || '') + ' ' + c.year + ' ' + c.make + ' ' + c.model));
  cars = cars.filter(c => isPriusJ(c) || !JUNK.test((c.desc || '') + ' ' + c.year + ' ' + c.make + ' ' + c.model));
  if (junkList.length) console.log(junkList.length + ' project/non-running car(s) excluded (Priuses exempt): ' + junkList.slice(0,12).map(c=>c.year+' '+c.make+' '+c.model).join(', '));

  // NO RED / GREEN / BLUE CARS (owner, 2026-07-06): hide these paint colors (keep neutrals —
  // white/silver/black/gray/brown/orange/purple/yellow/etc.). Cars with no listed color are kept.
  const HIDECOLOR = /\b(red|maroon|burgundy|crimson|scarlet|cardinal|green|lime|olive|forest|emerald|teal|blue|navy|turquoise|cobalt|indigo|aqua|azure)\b/i;
  const colorCut = cars.filter(c => c.color && HIDECOLOR.test(c.color)).length;
  cars = cars.filter(c => c.type==='Foreclosure' || c.type==='PVCars' || c.type === 'Room' || c.type === 'Batman' || !(c.color && HIDECOLOR.test(c.color)));
  if (colorCut) console.log(colorCut + ' red/green/blue car(s) hidden (owner color preference)');

  // BLOCKED MODELS (owner) — never shown, never imported. Add models here to hide them permanently.
  const BLOCKED = /\ballant[eé]?\b|\brambler\b|\bjeep\b|\bwillys\b|\bmercedes\b|\bbmw\b/i;   // Allante, Rambler, Jeeps/Willys, ALL Mercedes, ALL BMW (owner 2026-07-06)
  const blockCut = cars.filter(c => BLOCKED.test(c.make + ' ' + c.model)).length;
  cars = cars.filter(c => !BLOCKED.test(c.make + ' ' + c.model));
  if (blockCut) console.log(blockCut + ' blocked-model car(s) removed (Allante/Rambler/Jeep/Willys/Mercedes/BMW)');

  // FORD RULE (owner, 2026-07-06): no Ford cars — keep ONLY Ford trucks and vans.
  const FORD_KEEP = /\b(f-?\d{2,3}|ranger|courier|van|econoline|e-?[123]50|transit|club wagon|pickup|truck|dually|stake ?bed|flatbed)\b/i;
  const fordCut = cars.filter(c => /\bford\b/i.test(c.make) && !(c.type === 'Truck' || FORD_KEEP.test(c.model + ' ' + (c.sub || '')))).length;
  cars = cars.filter(c => !(/\bford\b/i.test(c.make) && !(c.type === 'Truck' || FORD_KEEP.test(c.model + ' ' + (c.sub || '')))));
  if (fordCut) console.log(fordCut + ' Ford car(s) removed (trucks & vans kept)');

  // location: all dealer (Atomic Motors) cars are in Henderson, Nevada; manual cars keep their own location.
  cars.forEach(function (c) { if (!c.location) c.location = 'Henderson, Nevada'; });

  // unique slugs
  const used = {};
  // OWNER RULE: never show duplicate car names. Manual dupes: keep lowest price. Dealer stock is never deleted — names get differentiated instead.
  (function(){
    var nameKey=function(c){
      var base=(c.year+' '+c.make+' '+c.model).toLowerCase().replace(/\s+/g,' ').trim();
      // Priuses: many genuinely-different listings share year+make+model, so key them uniquely
      // (true cross-post dupes were already removed upstream in merge-prius.js).
      if(/prius|sc ?-?430|tesla/i.test((c.make||'')+' '+(c.model||''))||c.type==='Land'||c.type==='House'||c.type==='Business'||c.type==='Antique'||c.type==='Rental'||c.type==='RV'||c.type==='Ebike'||c.type==='Free'||c.type==='Foreclosure'||c.type==='PVCars'||c.type === 'Room' || c.type === 'Batman') base+=' '+(c.oid||c.src||c.price);
      return base;
    };
    var groups={};
    cars.forEach(function(c){var k=nameKey(c);(groups[k]=groups[k]||[]).push(c);});
    var removed=0;
    Object.keys(groups).forEach(function(k){
      var grp=groups[k]; if(grp.length<2) return;
      var manuals=grp.filter(function(c){return c._manual;});
      if(manuals.length>1){
        manuals.sort(function(a,b){return (a.price||9e9)-(b.price||9e9)||((b.imgs||[]).length-(a.imgs||[]).length);});
        manuals.slice(1).forEach(function(c){c._dropDupe=true;removed++;});
      }
      var remain=grp.filter(function(c){return !c._dropDupe;});
      if(remain.length>1){
        remain.forEach(function(c,i){
          if(i===0) return;
          var tag=(c.color&&!/custom|patina|two-tone|other/i.test(c.color))?c.color:(c.stock?String(c.stock).toUpperCase():'No. '+(i+1));
          c.model=c.model+' ('+tag+')';
        });
      }
    });
    // same physical car cross-posted: same year+make+price+city among manual cars -> keep one (most photos)
    var carKey={};
    cars.forEach(function(c){
      if(!c._manual||c._dropDupe||c.type==='Land'||c.type==='House'||c.type==='Business'||c.type==='Antique'||c.type==='Rental'||c.type==='RV'||c.type==='Ebike'||c.type==='Free'||c.type==='Foreclosure'||c.type==='PVCars'||c.type === 'Room' || c.type === 'Batman') return; // Land/houses/businesses legitimately share price+area
      var k=[c.year,c.make,c.price,(c.location||'')].join('|').toLowerCase();
      if(!carKey[k]){carKey[k]=c;return;}
      var a=carKey[k];
      var win=((a.imgs||[]).length>=(c.imgs||[]).length)?a:c;
      var lose=(win===a)?c:a;
      lose._dropDupe=true;removed++;
      carKey[k]=win;
    });
    // LAND-specific dedupe: same seller reposts a parcel with the same price + same title —
    // key on price + normalized title-prefix (keep the one with the most photos).
    var landKey={};
    cars.forEach(function(c){
      if(c.type!=='Land'||c._dropDupe) return;
      var titlePrefix=String(c.model).toLowerCase().replace(/[^a-z0-9 ]/g,'').replace(/\s+/g,' ').trim().slice(0,34);
      var k='land|'+c.price+'|'+titlePrefix;
      if(!landKey[k]){landKey[k]=c;return;}
      var a=landKey[k];
      var win=((a.imgs||[]).length>=(c.imgs||[]).length)?a:c;
      ((win===a)?c:a)._dropDupe=true;removed++;
      landKey[k]=win;
    });
    var before=cars.length;
    cars=cars.filter(function(c){return !c._dropDupe;});
    if(removed) console.log(removed+' duplicate-name listing(s) removed (kept lowest price)');
  })();

  // SALVAGE SAFETY NET (owner, 2026-07-07): never show branded/salvage/no-title vehicles.
  // (enrich-all.js removes + tombstones them from the ad body; this catches any stored-desc stragglers.)
  (function(){
