  const paint=html.match(/paint:\s*<\/span>\s*<b>([^<]+)</i)||html.match(/"color"[^:]*:\s*"([^"]+)"/i);
  if(paint)attrs.color=paint[1].trim();
  return {imageUrls:urls, attrs};
}

