async function fR(u,bin,t){t=t||3;for(let a=0;a<t;a++){try{const r=await fetch(u,bin);if(r.status===200)return r;if(a===t-1)return r;}catch(e){if(a===t-1)return null;}await new Promise(r=>setTimeout(r,1200*(a+1)));}}
