const rep=[];
function apply(name,re,to){ const b=s.length; s=s.replace(re,function(){rep.push(name+' ✓');return to;}); if(s.length===b&&!rep.some(r=>r.startsWith(name))) rep.push(name+' ✗ NO-MATCH'); }

// 0) require the shared module once
if(!s.includes("require('./pin-gate.js')")){
  s=s.replace("const path = require('path');","const path = require('path');\nconst G = require('./pin-gate.js');");
