const fs=require('fs'),path=require('path'),zlib=require('zlib'),crypto=require('crypto'),https=require('https');
const {execSync}=require('child_process');
// Hosting SITE id to deploy to. Defaults to the domain's site; override with SITE env var
// (e.g. SITE=classiccarsforsale node _tools/rest-deploy.js). x-goog-user-project stays the
// billing/quota project id which is classiccarsforsale-co regardless of the target site.
const SITE=process.env.SITE||'classiccarsforsale-co';
const QUOTA_PROJECT='classiccarsforsale-co';
const TOKEN=execSync('gcloud auth print-access-token').toString().trim();
const H={'Authorization':'Bearer '+TOKEN,'x-goog-user-project':QUOTA_PROJECT};
console.error('deploy target site: '+SITE);

function req(method,url,headers,body){return new Promise((res,rej)=>{
  const u=new URL(url);
  const opt={method,hostname:u.hostname,path:u.pathname+u.search,headers:Object.assign({},H,headers)};
  const r=https.request(opt,resp=>{let d=[];resp.on('data',c=>d.push(c));resp.on('end',()=>{
    const buf=Buffer.concat(d);
    if(resp.statusCode>=200&&resp.statusCode<300)res({status:resp.statusCode,body:buf});
    else rej(new Error(method+' '+url+' -> '+resp.statusCode+' '+buf.toString().slice(0,200)));
  });});
  r.on('error',rej);
  r.setTimeout(60000,()=>r.destroy(new Error('timeout')));
  if(body)r.write(body);
  r.end();
});}

// retrying wrapper for the non-upload control calls (create version / populateFiles / finalize /
// release) — these are single small requests but the flaky connection times out on them; a bare
// failure used to kill the whole deploy. Uploads have their own retry loop below.
async function reqR(method,url,headers,body,tries){
  tries=tries||5;
  for(let a=0;a<tries;a++){
    try{ return await req(method,url,headers,body); }
    catch(e){ if(a===tries-1) throw e; console.error('  retry '+(a+1)+'/'+(tries-1)+' ('+e.message.slice(0,60)+')'); await new Promise(r=>setTimeout(r,2000*(a+1))); }
  }
}

// walk files, respect ignore
function walk(dir,base,out){
  for(const f of fs.readdirSync(dir)){
    if(f.startsWith('.'))continue;
    if(['_tools','_archive','node_modules'].includes(f))continue;
    const full=path.join(dir,f),rel=base+'/'+f;
    const st=fs.statSync(full);
    if(st.isDirectory())walk(full,rel,out);
    else if(f!=='firebase.json')out.push({full,rel,size:st.size,mtimeMs:st.mtimeMs});
  }
  return out;
}

(async()=>{
  const files=walk('.','',[]);
  // HASH CACHE (owner, 2026-07-08 "make it faster"): gzip+sha256 of ~9,000 photos took minutes
  // per deploy. Hashes are cached by size+mtime; unchanged files skip the read+gzip entirely.
  // gzip is deterministic (fixed level 9), so cached hashes match what a re-gzip would produce.
  const CACHEF=path.join(__dirname,'.deploy-hash-cache.json');
  let hcache={};try{hcache=JSON.parse(fs.readFileSync(CACHEF,'utf8'));}catch(e){}
  const map={}; // deployPath -> {hash, full, gz?}
  let hits=0,misses=0;
  for(const f of files){
    const c=hcache[f.rel];
    if(c&&c.size===f.size&&c.mtimeMs===f.mtimeMs){map[f.rel]={hash:c.hash,full:f.full};hits++;continue;}
    const gz=zlib.gzipSync(fs.readFileSync(f.full),{level:9});
    const hash=crypto.createHash('sha256').update(gz).digest('hex');
    map[f.rel]={hash,gz,full:f.full};
    hcache[f.rel]={size:f.size,mtimeMs:f.mtimeMs,hash};misses++;
  }
  // drop cache entries for files that no longer exist, then persist
  const liveRels=new Set(files.map(f=>f.rel));
  Object.keys(hcache).forEach(k=>{if(!liveRels.has(k))delete hcache[k];});
  try{fs.writeFileSync(CACHEF,JSON.stringify(hcache));}catch(e){}
  console.error('hashed '+files.length+' files ('+hits+' from cache, '+misses+' fresh)');
  const fb=JSON.parse(fs.readFileSync('firebase.json','utf8')).hosting;
  // create version with serving config
  console.error('creating version...');
  const config={cleanUrls:!!fb.cleanUrls,trailingSlashBehavior:fb.trailingSlash?'ADD':'REMOVE',headers:(fb.headers||[]).map(h=>({glob:h.source,headers:Object.fromEntries(h.headers.map(x=>[x.key,x.value]))}))};
  const cv=await reqR('POST',`https://firebasehosting.googleapis.com/v1beta1/sites/${SITE}/versions`,{'Content-Type':'application/json'},JSON.stringify({config}));
  const version=JSON.parse(cv.body).name; // sites/SITE/versions/ID
  console.error('version='+version);
  // populateFiles in batches
  const entries=Object.entries(map);
  let uploadUrl=null; const need=new Set();
  for(let i=0;i<entries.length;i+=1000){
    const batch=entries.slice(i,i+1000);
    const filesObj={};batch.forEach(([p,v])=>filesObj[p]=v.hash);
    const pf=await reqR('POST',`https://firebasehosting.googleapis.com/v1beta1/${version}:populateFiles`,{'Content-Type':'application/json'},JSON.stringify({files:filesObj}));
    const j=JSON.parse(pf.body);
    if(j.uploadUrl)uploadUrl=j.uploadUrl;
    (j.uploadRequiredHashes||[]).forEach(h=>need.add(h));
    console.error(`populated ${Math.min(i+1000,entries.length)}/${entries.length}, need so far: ${need.size}`);
  }
  console.error('TOTAL to upload: '+need.size+' (server already has the rest)');
  // build hash -> gz lookup; cache-hit files were never gzipped, so compress on demand here
  const byHash={};entries.forEach(([p,v])=>{byHash[v.hash]=v.gz||(()=>zlib.gzipSync(fs.readFileSync(v.full),{level:9}));});
  let done=0,fail=0;const needArr=[...need];
  function refreshToken(){ try{ const t=execSync('gcloud auth print-access-token').toString().trim(); H.Authorization='Bearer '+t; console.error('  (auth token refreshed)'); return true; }catch(e){ return false; } }
  // proactive token refresh on a timer so long deploys never age out mid-flight
  const tokTimer=setInterval(refreshToken, 25*60*1000);
  // PARALLEL uploads with a bounded worker pool — serial was too slow on this connection.
  const CONC=8; let idx=0;
  async function worker(){
    while(idx<needArr.length){
      const h=needArr[idx++]; let gz=byHash[h]; if(typeof gz==='function')gz=byHash[h]=gz(); let ok=false;
      for(let a=0;a<6&&!ok;a++){
        try{await req('POST',uploadUrl+'/'+h,{'Content-Type':'application/octet-stream'},gz);ok=true;}
        catch(e){ if(/-> 401/.test(e.message)) refreshToken(); if(a===5){console.error('  FAIL '+h+': '+e.message);}else await new Promise(r=>setTimeout(r,1200*(a+1)));}
      }
      if(ok){done++;if(done%200===0)console.error(`  uploaded ${done}/${needArr.length}`);}else fail++;
    }
  }
  await Promise.all(Array.from({length:Math.min(CONC,needArr.length||1)},()=>worker()));
  clearInterval(tokTimer);
  console.error(`uploaded ${done}, failed ${fail}`);
  if(fail>0){console.error('ABORT: '+fail+' uploads failed');process.exit(1);}
  // finalize
  await reqR('PATCH',`https://firebasehosting.googleapis.com/v1beta1/${version}?update_mask=status`,{'Content-Type':'application/json'},JSON.stringify({status:'FINALIZED'}));
  console.error('finalized');
  // release
  await reqR('POST',`https://firebasehosting.googleapis.com/v1beta1/sites/${SITE}/releases?versionName=${version}`,{'Content-Type':'application/json'},JSON.stringify({}));
  console.error('RELEASED ✅ '+version);
})().catch(e=>{console.error('ERROR: '+e.message);process.exit(1);});

