// Marks cars SOLD (never deletes) when their Craigslist listing is gone (deleted/expired/removed).
// Usage: node _tools/sold-check.js [SAMPLE]   (SAMPLE=number → only check a random sample, report only)
const https=require('https'),fs=require('fs'),path=require('path');
