function gone(res){ if(res.status===404) return true; if(res.status!==200) return false;
  return /has been deleted by its author|this posting has expired|has been flagged for removal|posting has been removed|no longer available|<title>[^<]*(expired|deleted)/i.test(res.body); }
(async()=>{
