const FSD=/\b(fsd|full self.?driv\w*|self.?driving (capability|package|included|mode)|lifetime self.?driv\w*)\b/i;

(async()=>{
  const MANUAL=path.join(ROOT,'_tools','manual.json');
  const manual=JSON.parse(fs.readFileSync(MANUAL,'utf8'));
  const teslas=manual.filter(e=>/tesla/i.test(e.make||'')&&e.src);
  let enriched=0,fsdCount=0,dead=0;const CONC=6;let idx=0;
  async function worker(){
    while(idx<teslas.length){
      const e=teslas[idx++];
      const r=await fetchR(e.src);
      if(!r||r.status!==200){dead++;continue;}
      const html=r.body;
      const body=((html.match(/<section id="postingbody">([\s\S]*?)<\/section>/)||[])[1]||'').replace(/<[^>]+>/g,' ');
      const hay=(e.desc||'')+' '+e.src+' '+body;
