  let c=(slug||'').split(/-(?:lexus|sc430|sc-430|20\d\d)/)[0].replace(/-/g,' ').trim().replace(/\b\w/g,m=>m.toUpperCase());
  const lc=c.toLowerCase();
  const state=NV.has(lc)?'Nevada':AZ.has(lc)?'Arizona':'California';
  return c?(c+', '+state):'California';
}
